// Ground (lon, lat) to image (x, y). Returns null when the point does not project onto the image.
export function groundToImage(model, lon, lat) {
  const x = (lon - model.lon0) / model.dlon;
  const y = (model.lat0 - lat) / model.dlat;
  if (x < 0 || y < 0 || x > model.width || y > model.height) return null;
  return { x, y };
}

