import { groundToImage } from './model.js';

// AOI from Graphic: the image rectangle around a drawn graphic.
export function aoiFromGraphic(layer, graphic) {
  const pixels = graphic.vertices.map(([lon, lat]) => groundToImage(layer.model, lon, lat));
  const xs = pixels.map((p) => p.x);
  const ys = pixels.map((p) => p.y);
  return {
    x0: Math.floor(Math.min(...xs)),
    y0: Math.floor(Math.min(...ys)),
    x1: Math.ceil(Math.max(...xs)),
    y1: Math.ceil(Math.max(...ys)),
  };
}
